    reversed = int(str(x)[::-1])
    return x != reversed and sum_div(x) == sum_div(reversed)

required = [x for x in range(528, 10**4) if is_required(x)]

def equal_sigma1(nMax):
    return sum(x for x in required if x <= nMax)
